- All feasibility checks passed; plan is feasible.", "solve_py": "#!/usr/bin/env python3
"""Airport gate assignment solver (PySCIPOpt)."""
import csv
import json
import os
import sys

from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions"
SOL_PATH = os.path.join(OUT, "solution.csv")


def read_csv(name):
    with open(os.path.join(DATA, name), newline="") as f:
        return list(csv.DictReader(f))


def main():
    os.makedirs(OUT, exist_ok=True)

    with open(os.path.join(DATA, "config.json")) as f:
        cfg = json.load(f)

    flights = read_csv("flights.csv")
    gates = read_csv("gates.csv")
    facilities = read_csv("facility_capacity.csv")
    adj_conf = read_csv("adjacent_gate_conflicts.csv")
    mars = read_csv("mars_gate_groups.csv")
    rotations = read_csv("aircraft_rotations.csv")
    remote_limits = read_csv("remote_bank_limits.csv")
    turn_bufs = read_csv("gate_turnaround_buffers.csv")
    handler_caps = read_csv("handler_capacity.csv")
    taxi_meters = read_csv("taxiway_metering.csv")
    connections = read_csv("connections.csv")

    W = cfg["scoring"]
    WF = cfg["walking_formula"]
    APRON_POS = cfg["remote_apron_positions"]

    F = [r["flight_id"] for r in flights]
    G = [r["gate_id"] for r in gates]
    fid = {r["flight_id"]: r for r in flights}
    gid = {r["gate_id"]: r for r in gates}

    # Robust intervals
    start = {}
    end = {}
    for f in F:
        r = fid[f]
        start[f] = int(r["arrival_minute"]) - int(r["buffer_before_arrival"])
        end[f] = int(r["departure_minute"]) + int(r["buffer_after_departure"])

    def overlaps(f1, f2):
        return start[f1] < end[f2] and start[f2] < end[f1]

    # Turnaround extra buffer lookup: (prev_region, next_region, prev_class, next_class) -> extra
    # Rule applies if prev_class >= prev_min and next_class >= next_min.
    def extra_buffer(f_prev, f_next):
        rp = fid[f_prev]
        rn = fid[f_next]
        cp = int(rp["aircraft_class"])
        cn = int(rn["aircraft_class"])
        best = 0
        for tb in turn_bufs:
            if tb["previous_region"] == rp["traffic_region"] and tb["next_region"] == rn["traffic_region"]:
                if cp >= int(tb["previous_aircraft_class_min"]) and cn >= int(tb["next_aircraft_class_min"]):
                    best = max(best, int(tb["extra_buffer_minutes"]))
        return best

    # Gate compatibility
    def gate_ok(f, g):
        r = fid[f]
        gg = gid[g]
        if int(r["aircraft_class"]) > int(gg["max_aircraft_class"]):
            return False
        reg = r["traffic_region"]
        if reg == "domestic" and not gg["allow_domestic"] == "1":
            return False
        if reg == "schengen" and not gg["allow_schengen"] == "1":
            return False
        if reg == "international" and not gg["allow_international"] == "1":
            return False
        return True

    # Rotations: verify min turn feasible
    for rot in rotations:
        fi = rot["inbound_flight_id"]
        fo = rot["follow_on_flight_id"]
        if int(rot["same_gate_required"]) == 1:
            gap = start[fo] - end[fi]
            if gap < int(rot["min_turn_minutes"]):
                # infeasible rotation; but data should be consistent
                print(f"WARNING: rotation {rot['rotation_id']} min turn not satisfiable: gap={gap}")

    # Facility capacities
    sec_cap = {}  # (terminal, bank) -> cap
    imm_cap = {}
    bus_cap = {}  # terminal -> cap
    for fc in facilities:
        t = fc["terminal"]
        b = fc["bank_id"]
        if fc["flow_type"] == "security_departure":
            sec_cap[(t, b)] = int(fc["capacity_passengers"])
        elif fc["flow_type"] == "immigration_arrival":
            imm_cap[(t, b)] = int(fc["capacity_passengers"])
        elif fc["flow_type"] == "remote_bus":
            bus_cap[t] = int(fc["capacity_passengers"])

    # Handler capacities
    hcap_total = {}  # (handler, bank) -> max
    hcap_wide = {}
    for hc in handler_caps:
        hcap_total[(hc["handler_id"], hc["bank_id"])] = int(hc["max_turnarounds"])
        hcap_wide[(hc["handler_id"], hc["bank_id"])] = int(hc["max_widebody_turnarounds"])

    # Remote bank limits
    rbank = {r["bank_id"]: int(r["max_remote_turnarounds"]) for r in remote_limits}

    # Taxiway meters: meter_id -> (bank, {gate: max})
    meters = {}
    for tm in taxi_meters:
        m = tm["meter_id"]
        if m not in meters:
            meters[m] = {"bank": tm["bank_id"], "gates": {}, "max": int(tm["max_departures"])}
        meters[m]["gates"][tm["gate_id"]] = int(tm["max_departures"])

    # Build model
    model = Model("airport_gate_assignment")
    model.setParam("gaprel", 0.0005)
    tl = 300.0
    env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env is not None:
        try:
            tl = min(tl, float(env))
        except ValueError:
            pass
    model.setParam("limits/time", tl)

    x = {}
    y = {}
    for f in F:
        r = fid[f]
        for g in G:
            if gate_ok(f, g):
                x[(f, g)] = model.addVar(name=f"x_{f}_{g}", vtype="B", lb=0, ub=1, obj=0.0)
        if int(r["must_contact_gate"]) == 0:
            y[f] = model.addVar(name=f"y_{f}", vtype="B", lb=0, ub=1, obj=0.0)

    # Assignment constraints
    for f in F:
        r = fid[f]
        terms = [x[(f, g)] for g in G if (f, g) in x]
        if int(r["must_contact_gate"]) == 0:
            terms.append(y[f])
        model.addCons(quicksum(terms) == 1, name=f"assign_{f}")

    # Gate overlap constraints
    for g in G:
        fl = [f for f in F if (f, g) in x]
        for i in range(len(fl)):
            for j in range(i + 1, len(fl)):
                f1, f2 = fl[i], fl[j]
                if overlaps(f1, f2):
                    model.addCons(x[(f1, g)] + x[(f2, g)] <= 1, name=f"ovl_{g}_{f1}_{f2}")

    # Turnaround buffer constraints (gate reuse, ordered)
    for g in G:
        fl = [f for f in F if (f, g) in x]
        for i in range(len(fl)):
            for j in range(len(fl)):
                if i == j:
                    continue
                f1, f2 = fl[i], fl[j]
                # f1 before f2
                if end[f1] <= start[f2]:
                    buf = extra_buffer(f1, f2)
                    if start[f2] - end[f1] < buf:
                        model.addCons(x[(f1, g)] + x[(f2, g)] <= 1, name=f"buf_{g}_{f1}_{f2}")

    # Adjacent conflicts
    for ac in adj_conf:
        ga, gb = ac["gate_id_a"], ac["gate_id_b"]
        th = int(ac["aircraft_class_threshold"])
        for f1 in F:
            for f2 in F:
                if f1 == f2:
                    continue
                if not overlaps(f1, f2):
                    continue
                if max(int(fid[f1]["aircraft_class"]), int(fid[f2]["aircraft_class"])) < th:
                    continue
                if (f1, ga) in x and (f2, gb) in x:
                    model.addCons(x[(f1, ga)] + x[(f2, gb)] <= 1, name=f"adj_{ga}_{gb}_{f1}_{f2}")
                if (f1, gb) in x and (f2, ga) in x:
                    model.addCons(x[(f1, gb)] + x[(f2, ga)] <= 1, name=f"adj_{gb}_{ga}_{f1}_{f2}")

    # MARS conflicts
    for mg in mars:
        ga, gb = mg["gate_id_a"], mg["gate_id_b"]
        th = int(mg["widebody_class_threshold"])
        for f1 in F:
            for f2 in F:
                if f1 == f2:
                    continue
                if not overlaps(f1, f2):
                    continue
                if max(int(fid[f1]["aircraft_class"]), int(fid[f2]["aircraft_class"])) < th:
                    continue
                if (f1, ga) in x and (f2, gb) in x:
                    model.addCons(x[(f1, ga)] + x[(f2, gb)] <= 1, name=f"mars_{ga}_{gb}_{f1}_{f2}")
                if (f1, gb) in x and (f2, ga) in x:
                    model.addCons(x[(f1, gb)] + x[(f2, ga)] <= 1, name=f"mars_{gb}_{ga}_{f1}_{f2}")

    # Rotations
    for rot in rotations:
        fi = rot["inbound_flight_id"]
        fo = rot["follow_on_flight_id"]
        if int(rot["same_gate_required"]) == 1:
            for g in G:
                if (fi, g) in x and (fo, g) in x:
                    model.addCons(x[(fi, g)] == x[(fo, g)], name=f"rot_{rot['rotation_id']}_{g}")
            # Also ensure they can't be on apron if same gate required
            for f in (fi, fo):
                if f in y:
                    model.addCons(y[f] == 0, name=f"rot_noy_{rot['rotation_id']}_{f}")

    # Apron capacity at event times
    apron_flights = [f for f in F if f in y]
    if apron_flights:
        times = sorted(set(list(start.values()) + list(end.values())))
        for t in times:
            active = [f for f in apron_flights if start[f] <= t < end[f]]
            if len(active) > APRON_POS:
                model.addCons(quicksum(y[f] for f in active) <= APRON_POS, name=f"apron_{t}")
        # Also check all pairs that overlap (stronger for small capacity)
        for i in range(len(apron_flights)):
            for j in range(i + 1, len(apron_flights)):
                f1, f2 = apron_flights[i], apron_flights[j]
                if overlaps(f1, f2) and APRON_POS == 1:
                    model.addCons(y[f1] + y[f2] <= 1, name=f"apron_pair_{f1}_{f2}")

    # Remote bank limits
    for b, lim in rbank.items():
        fl = [f for f in apron_flights if fid[f]["departure_bank"] == b]
        if fl:
            model.addCons(quicksum(y[f] for f in fl) <= lim, name=f"rbank_{b}")

    # Handler capacities
    # For gate flights: handler = gate's handler. For apron: H_REMOTE_{preferred_terminal}.
    handlers = set(gid[g]["handler_id"] for g in G)
    for h in handlers:
        for b in ["D_MORNING", "D_MIDDAY", "D_AFTERNOON", "D_EVENING", "D_LATE"]:
            if (h, b) not in hcap_total:
                continue
            terms = []
            wterms = []
            for f in F:
                r = fid[f]
                if r["departure_bank"] != b:
                    continue
                # Gate assignments with this handler
                for g in G:
                    if gid[g]["handler_id"] == h and (f, g) in x:
                        terms.append(x[(f, g)])
                        if int(r["aircraft_class"]) == 2:
                            wterms.append(x[(f, g)])
                # Apron assignment with remote handler
                if h.startswith("H_REMOTE"):
                    pt = h.replace("H_REMOTE_", "")
                    if r["preferred_terminal"] == pt and f in y:
                        terms.append(y[f])
                        if int(r["aircraft_class"]) == 2:
                            wterms.append(y[f])
            if terms:
                model.addCons(quicksum(terms) <= hcap_total[(h, b)], name=f"hcap_{h}_{b}")
            if wterms:
                model.addCons(quicksum(wterms) <= hcap_wide[(h, b)], name=f"hcapw_{h}_{b}")

    # Security capacity: departing pax by terminal and departure bank
    # terminal(f) = gate terminal if on gate, else preferred terminal
    for (t, b), cap in sec_cap.items():
        terms = []
        for f in F:
            r = fid[f]
            if r["departure_bank"] != b:
                continue
            dep = int(r["departing_passengers"])
            for g in G:
                if gid[g]["terminal"] == t and (f, g) in x:
                    terms.append(dep * x[(f, g)])
            if r["preferred_terminal"] == t and f in y:
                terms.append(dep * y[f])
        if terms:
            model.addCons(quicksum(terms) <= cap, name=f"sec_{t}_{b}")

    # Immigration capacity: arriving international pax by terminal and arrival bank
    for (t, b), cap in imm_cap.items():
        terms = []
        for f in F:
            r = fid[f]
            if r["arrival_bank"] != b or r["traffic_region"] != "international":
                continue
            arr = int(r["arriving_passengers"])
            for g in G:
                if gid[g]["terminal"] == t and (f, g) in x:
                    terms.append(arr * x[(f, g)])
            if r["preferred_terminal"] == t and f in y:
                terms.append(arr * y[f])
        if terms:
            model.addCons(quicksum(terms) <= cap, name=f"imm_{t}_{b}")

    # Remote bus capacity: total pax (arr+dep) by preferred terminal
    for t, cap in bus_cap.items():
        terms = []
        for f in F:
            r = fid[f]
            if r["preferred_terminal"] != t or f not in y:
                continue
            terms.append((int(r["arriving_passengers"]) + int(r["departing_passengers"])) * y[f])
        if terms:
            model.addCons(quicksum(terms) <= cap, name=f"bus_{t}")

    # Taxiway metering
    for m, md in meters.items():
        b = md["bank"]
        terms = []
        for f in F:
            if fid[f]["departure_bank"] != b:
                continue
            for g in md["gates"]:
                if (f, g) in x:
                    terms.append(x[(f, g)])
        if terms:
            model.addCons(quicksum(terms) <= md["max"], name=f"meter_{m}")

    # Connections
    # Walk time computation:
    # Both gates same terminal: base + per_grid * |x1 - x2|
    # Different terminals: base + per_grid * |x1 - x2| + inter_terminal (use base of one? use same_terminal_base + inter)
    # Actually: same terminal: base_walk + per_grid * dist. Different: base_walk + per_grid*dist + inter_terminal.
    # If either apron: use processing terminal, add remote_connection_extra.
    # Interpretation: if either is apron, walk = (gate walk to other or base) + remote_extra.
    # Let's define:
    #   If both gates: walk = base + per_grid*|x1-x2| + (inter if different terminals else 0)
    #   If f1 apron, f2 gate: walk = base + per_grid*|x2 - x_pref1| ... hmm, apron has no coord.
    #   Simpler: if either apron: walk = base + inter/remote_extra depending.
    #   Let's use: if either apron: walk = base_walk + remote_extra + (inter if terminals differ else 0)
    #   where terminal of apron flight = preferred terminal.
    base_w = WF["same_terminal_base_walk"]
    per_grid = WF["walk_minutes_per_grid"]
    inter_t = WF["inter_terminal_transfer_minutes"]
    remote_extra = WF["remote_connection_extra_minutes"]

    def walk_both_gates(f1, g1, f2, g2):
        t1 = gid[g1]["terminal"]
        t2 = gid[g2]["terminal"]
        d = abs(int(gid[g1]["x_coord"]) - int(gid[g2]["x_coord"]))
        w = base_w + per_grid * d
        if t1 != t2:
            w += inter_t
        return w

    def walk_apron_gate(f_apron, f_gate, g_gate):
        t_ap = fid[f_apron]["preferred_terminal"]
        t_g = gid[g_gate]["terminal"]
        w = base_w + remote_extra
        if t_ap != t_g:
            w += inter_t
        return w

    def walk_both_apron(f1, f2):
        t1 = fid[f1]["preferred_terminal"]
        t2 = fid[f2]["preferred_terminal"]
        w = base_w + remote_extra
        if t1 != t2:
            w += inter_t
        return w

    z = {}
    wa = {}
    wb = {}
    e = {}
    for c in connections:
        cid = c["connection_id"]
        fi = c["inbound_flight_id"]
        fo = c["outbound_flight_id"]
        pax = int(c["passenger_count"])
        maxw = int(c["max_walk_minutes"])
        crit = int(c["critical_connection"])

        # z variables for gate-gate
        for g1 in G:
            if (fi, g1) not in x:
                continue
            for g2 in G:
                if (fo, g2) not in x:
                    continue
                z[(cid, g1, g2)] = model.addVar(name=f"z_{cid}_{g1}_{g2}", vtype="B", lb=0, ub=1, obj=0.0)
        # wa: inbound apron, outbound gate
        if fi in y:
            for g2 in G:
                if (fo, g2) in x:
                    wa[(cid, g2)] = model.addVar(name=f"wa_{cid}_{g2}", vtype="B", lb=0, ub=1, obj=0.0)
        # wb: outbound apron, inbound gate
        if fo in y:
            for g1 in G:
                if (fi, g1) in x:
                    wb[(cid, g1)] = model.addVar(name=f"wb_{cid}_{g1}", vtype="B", lb=0, ub=1, obj=0.0)

        e[cid] = model.addVar(name=f"e_{cid}", vtype="C", lb=0, ub=None, obj=0.0)

        # Linking constraints
        for g1 in G:
            if (fi, g1) not in x:
                continue
            for g2 in G:
                if (fo, g2) not in x:
                    continue
                v = z[(cid, g1, g2)]
                model.addCons(v <= x[(fi, g1)], name=f"zl1_{cid}_{g1}_{g2}")
                model.addCons(v <= x[(fo, g2)], name=f"zl2_{cid}_{g1}_{g2}")
                model.addCons(v >= x[(fi, g1)] + x[(fo, g2)] - 1, name=f"zl3_{cid}_{g1}_{g2}")

        if fi in y:
            for g2 in G:
                if (fo, g2) not in x:
                    continue
                v = wa[(cid, g2)]
                model.addCons(v <= y[fi], name=f"wal1_{cid}_{g2}")
                model.addCons(v <= x[(fo, g2)], name=f"wal2_{cid}_{g2}")
                model.addCons(v >= y[fi] + x[(fo, g2)] - 1, name=f"wal3_{cid}_{g2}")

        if fo in y:
            for g1 in G:
                if (fi, g1) not in x:
                    continue
                v = wb[(cid, g1)]
                model.addCons(v <= x[(fi, g1)], name=f"wbl1_{cid}_{g1}")
                model.addCons(v <= y[fo], name=f"wbl2_{cid}_{g1}")
                model.addCons(v >= x[(fi, g1)] + y[fo] - 1, name=f"wbl3_{cid}_{g1}")

        # Walk constraints
        # Critical: walk <= maxw
        # Noncritical: e >= walk - maxw
        if crit == 1:
            # Build walk expression
            wexpr = []
            for g1 in G:
                if (fi, g1) not in x:
                    continue
                for g2 in G:
                    if (fo, g2) not in x:
                        continue
                    wexpr.append(walk_both_gates(fi, g1, fo, g2) * z[(cid, g1, g2)])
            if fi in y:
                for g2 in G:
                    if (fo, g2) not in x:
                        continue
                    wexpr.append(walk_apron_gate(fi, fo, g2) * wa[(cid, g2)])
            if fo in y:
                for g1 in G:
                    if (fi, g1) not in x:
                        continue
                    wexpr.append(walk_apron_gate(fo, fi, g1) * wb[(cid, g1)])
            if fi in y and fo in y:
                # both apron: need a variable for that case
                # Add a variable for both-apron
                vba = model.addVar(name=f"vba_{cid}", vtype="B", lb=0, ub=1, obj=0.0)
                model.addCons(vba <= y[fi], name=f"vba1_{cid}")
                model.addCons(vba <= y[fo], name=f"vba2_{cid}")
                model.addCons(vba >= y[fi] + y[fo] - 1, name=f"vba3_{cid}")
                wexpr.append(walk_both_apron(fi, fo) * vba)
            if wexpr:
                model.addCons(quicksum(wexpr) <= maxw, name=f"crit_{cid}")
        else:
            wexpr = []
            for g1 in G:
                if (fi, g1) not in x:
                    continue
                for g2 in G:
                    if (fo, g2) not in x:
                        continue
                    wexpr.append(walk_both_gates(fi, g1, fo, g2) * z[(cid, g1, g2)])
            if fi in y:
                for g2 in G:
                    if (fo, g2) not in x:
                        continue
                    wexpr.append(walk_apron_gate(fi, fo, g2) * wa[(cid, g2)])
            if fo in y:
                for g1 in G:
                    if (fi, g1) not in x:
                        continue
                    wexpr.append(walk_apron_gate(fo, fi, g1) * wb[(cid, g1)])
            if fi in y and fo in y:
                vba = model.addVar(name=f"vba_{cid}", vtype="B", lb=0, ub=1, obj=0.0)
                model.addCons(vba <= y[fi], name=f"vba1_{cid}")
                model.addCons(vba <= y[fo], name=f"vba2_{cid}")
                model.addCons(vba >= y[fi] + y[fo] - 1, name=f"vba3_{cid}")
                wexpr.append(walk_both_apron(fi, fo) * vba)
            if wexpr:
                model.addCons(e[cid] >= quicksum(wexpr) - maxw, name=f"excess_{cid}")

    # Objective
    obj_terms = []
    # Gate walking cost: arr*baggage + dep*security
    for (f, g), v in x.items():
        r = fid[f]
        gg = gid[g]
        cost = int(r["arriving_passengers"]) * int(gg["walk_to_baggage"]) + int(r["departing_passengers"]) * int(gg["walk_to_security"])
        obj_terms.append(W["walk_cost_per_passenger_minute"] * cost * v)
    # Taxi cost
    for (f, g), v in x.items():
        gg = gid[g]
        obj_terms.append(W["taxi_cost_per_minute"] * (int(gg["taxi_in_minutes"]) + int(gg["taxi_out_minutes"])) * v)
    # Terminal mismatch
    for (f, g), v in x.items():
        r = fid[f]
        if gid[g]["terminal"] != r["preferred_terminal"]:
            obj_terms.append(W["terminal_mismatch_penalty"] * int(r["priority_weight"]) * v)
    # Apron penalties
    for f, v in y.items():
        r = fid[f]
        pax = int(r["arriving_passengers"]) + int(r["departing_passengers"])
        obj_terms.append((W["remote_apron_fixed_penalty"] + W["remote_apron_passenger_penalty"] * pax) * v)
    # Connection walk cost
    for c in connections:
        cid = c["connection_id"]
        fi = c["inbound_flight_id"]
        fo = c["outbound_flight_id"]
        pax = int(c["passenger_count"])
        cterms = []
        for g1 in G:
            if (fi, g1) not in x:
                continue
            for g2 in G:
                if (fo, g2) not in x:
                    continue
                if (cid, g1, g2) in z:
                    cterms.append(walk_both_gates(fi, g1, fo, g2) * z[(cid, g1, g2)])
        if fi in y:
            for g2 in G:
                if (fo, g2) not in x:
                    continue
                if (cid, g2) in wa:
                    cterms.append(walk_apron_gate(fi, fo, g2) * wa[(cid, g2)])
        if fo in y:
            for g1 in G:
                if (fi, g1) not in x:
                    continue
                if (cid, g1) in wb:
                    cterms.append(walk_apron_gate(fo, fi, g1) * wb[(cid, g1)])
        if fi in y and fo in y:
            # find vba variable
            for v in model.getVars():
                if v.name == f"vba_{cid}":
                    cterms.append(walk_both_apron(fi, fo) * v)
                    break
        if cterms:
            obj_terms.append(W["connection_walk_cost_per_passenger_minute"] * pax * quicksum(cterms))
    # Noncritical excess
    for c in connections:
        if int(c["critical_connection"]) == 0:
            obj_terms.append(W["noncritical_connection_excess_penalty"] * e[c["connection_id"]])

    obj_expr = quicksum(obj_terms) if obj_terms else 0.0
    model.setObjective(obj_expr, sense="minimize")

    # Solve
    model.optimize()
    status = model.getStatus()
    print(f"Solver status: {status}")
    print(f"Objective: {model.getObjVal():.8f}")
    print(f"Time: {model.getNSols()} solutions")

    # Extract solution
    solution = {}
    for f in F:
        r = fid[f]
        assigned = False
        for g in G:
            if (f, g) in x:
                val = model.getVal(x[(f, g)])
                if val > 0.5:
                    solution[f] = ("gate", g)
                    assigned = True
                    break
        if not assigned and f in y:
            val = model.getVal(y[f])
            if val > 0.5:
                solution[f] = ("apron", "")
                assigned = True
        if not assigned:
            # Fallback: assign to first compatible gate or apron
            for g in G:
                if gate_ok(f, g):
                    solution[f] = ("gate", g)
                    break
            else:
                if int(r["must_contact_gate"]) == 0:
                    solution[f] = ("apron", "")
                else:
                    solution[f] = ("gate", G[0])

    # Validation
    print("\n=== Validation ===")
    ok = True
    # Check all flights assigned
    for f in F:
        if f not in solution:
            print(f"ERROR: {f} not assigned")
            ok = False

    # Check gate compatibility
    for f, (atype, g) in solution.items():
        if atype == "gate" and not gate_ok(f, g):
            print(f"ERROR: {f} assigned to incompatible gate {g}")
            ok = False

    # Check gate overlaps
    for g in G:
        fl = [f for f, (a, gg) in solution.items() if a == "gate" and gg == g]
        for i in range(len(fl)):
            for j in range(i + 1, len(fl)):
                if overlaps(fl[i], fl[j]):
                    print(f"ERROR: overlap on gate {g}: {fl[i]} {fl[j]}")
                    ok = False

    # Check apron capacity
    af = [f for f, (a, g) in solution.items() if a == "apron"]
    times = sorted(set([start[f] for f in af] + [end[f] for f in af]))
    for t in times:
        active = [f for f in af if start[f] <= t < end[f]]
        if len(active) > APRON_POS:
            print(f"ERROR: apron capacity exceeded at t={t}: {len(active)}")
            ok = False

    print(f"Validation {'PASSED' if ok else 'FAILED'}")

    # Write solution
    with open(SOL_PATH, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["flight_id", "assignment_type", "gate_id"])
        for f in F:
            atype, g = solution[f]
            w.writerow([f, atype, g])
    print(f"Solution written to {SOL_PATH}")

    model.free()


